"""Write the local review gallery for five native Godot exports."""
from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parents[2]
BATCH=ROOT/'shorts/godot/batch01'
labels=['Headphone confidence','Wrong-class runway','One quick doodle','Same beat, different energy','Act natural']
subs=['A shy start becomes her own music video.','Collar, shades, shoes… then the wrong doorway.','The sketchbook takes over the frame.','Nemi commits. ADB gives one tiny response.','The photographer ends up flustered.']
tracks={x['id']:x for x in json.loads((ROOT/'shorts/assets/music/batch01/catalog.json').read_text())}
entries=[]
for i,p in enumerate(sorted(BATCH.glob('0*/short.json'))):
 c=json.loads(p.read_text());folder='/'+str(p.parent.relative_to(ROOT));slug=Path(c['music']['file']).stem;t=tracks[slug]
 revision=json.loads((p.parent/'review/current.json').read_text())['revision']
 e={'title':labels[i],'subtitle':subs[i],'artist':t['artist'],'track':t['title'],'url':folder+f'/renders/{c["id"]}_{revision}_1080x1920.mp4','poster':folder+'/review/poster.jpg','direction':folder+'/DIRECTION.md','download':folder+f'/renders/{c["id"]}_{revision}_1080x1920.mp4','source':t['catalogUrl'],'cuts':[[s['frame']/30,f'{s["frame"]/30:.2f}s'] for s in c['shots']],'duration':15,'number':str(i+1).zfill(2)}
 entries.append(e)
page='''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ADB + Nemi · Five ink edits</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#eeeae4;color:#292930;font:15px system-ui,-apple-system,sans-serif}button,a,input{font:inherit}button{cursor:pointer}header{max-width:1180px;margin:auto;padding:27px 30px 20px;display:flex;align-items:end;justify-content:space-between;gap:20px;border-bottom:1px solid #d8d1c8}h1{font-size:34px;letter-spacing:-1.3px;line-height:1.06;margin:7px 0}header p{margin:0;color:#747075;font-size:14px}.eyebrow{font-size:11px;letter-spacing:.18em;font-weight:700;color:#776a83}header nav{display:flex;gap:18px;flex-wrap:wrap}a{color:#6d587b;text-decoration:none}a:hover{text-decoration:underline}main{max-width:1180px;margin:auto;padding:25px 30px;display:grid;grid-template-columns:minmax(290px,460px) 1fr;gap:50px}.screen{display:flex;justify-content:center;background:#e3ded8;border-radius:14px;overflow:hidden;box-shadow:0 16px 38px #473d3412}video{display:block;width:auto;max-width:100%;height:min(66vh,675px);background:#dedad6}.controls{display:flex;gap:8px;align-items:center;margin-top:15px}button.primary{background:#38303f;color:#fff;border:0;border-radius:8px;padding:11px 20px;font-weight:600}button.quiet{background:#e2dbd3;border:1px solid #d4ccc2;color:#39313e;border-radius:8px;padding:10px 14px}#clock{margin-left:auto;font-size:12px;color:#777;white-space:nowrap}.list{display:flex;flex-direction:column;gap:8px}.choice{border:1px solid transparent;background:transparent;border-radius:12px;text-align:left;padding:12px;display:grid;grid-template-columns:57px 1fr;gap:16px;align-items:center;color:#35313b;min-height:108px}.choice.active{background:#faf7f2;border-color:#d2c6d8;box-shadow:0 5px 20px #50403f08}.choice:hover{background:#f8f4ee}.choice img{width:57px;height:89px;object-fit:cover;border-radius:4px}.choice b{display:block;font-size:17px;font-weight:650;margin-bottom:4px;letter-spacing:-.4px}.choice small{display:block;color:#7c7281;font-size:12px;line-height:1.5}.choice span.num{font-size:10px;letter-spacing:.16em;color:#9b8ca4;display:block;margin-bottom:4px}.detail{padding:18px 10px 0;border-top:1px solid #d7cec5;margin-top:11px}.detail p{font-size:13px;line-height:1.6;color:#777079;margin:0 0 10px}.detail .links{display:flex;gap:18px;font-size:12px}.cuts{display:flex;gap:5px;flex-wrap:wrap;margin-top:15px}.cuts button{font-size:10px;letter-spacing:.02em;border:1px solid #d6cdd9;background:transparent;padding:5px 7px;border-radius:5px;color:#756779}.footer{max-width:1180px;margin:auto;padding:0 30px 25px;font-size:11px;color:#938a91}.footer a{margin-right:20px}@media(max-width:800px){main{gap:24px;padding:20px;grid-template-columns:minmax(250px,1fr) 1fr}header{padding:20px}header nav{font-size:12px}h1{font-size:27px}.choice{grid-template-columns:40px 1fr;gap:10px;padding:8px;min-height:87px}.choice img{width:40px;height:65px}.choice b{font-size:14px}.choice small{font-size:10px}}@media(max-width:580px){header{display:block}header nav{margin-top:14px}main{display:flex;flex-direction:column;gap:25px}.choice{grid-template-columns:45px 1fr}.choice img{width:45px;height:76px}video{height:67vh}.choice b{font-size:17px}.choice small{font-size:12px}.detail{padding-top:18px}.footer{padding:0 20px 25px}}
</style></head><body>
<header><div><div class="eyebrow">ADB + NEMI / INK EDITS · 01</div><h1>Five songs. Five moods.</h1><p>15-second edits · hand-authored ink, shading & doodles</p></div><nav><a href="/shorts/review/rebuild/index.html">Approved proof</a><a href="/shorts/review/references/index.html">References</a><a href="/shorts/godot/batch01/README.md">Production notes</a></nav></header>
<main><section><div class="screen"><video id="player" controls loop playsinline preload="metadata"></video></div><div class="controls"><button id="play" class="primary">Play edit</button><button id="pause" class="quiet">Pause</button><button id="restart" class="quiet">Restart</button><output id="clock">0.00 / 15.00 s</output></div><div class="cuts" id="cuts" aria-label="Jump to edit cue"></div></section><section><div class="list" id="list"></div><div class="detail"><p id="description"></p><div class="links"><a id="download" download>Download MP4</a><a id="direction">Shot direction</a><a id="music" target="_blank" rel="noreferrer">Music source</a></div></div></section></main>
<div class="footer"><a href="/shorts/godot/WORKFLOW.md">Godot workflow</a><a href="/shorts/godot/batch01/review/QA.md">Render & sound checks</a><a href="/shorts/godot/batch01/review/ISOLATION.md">Storytime isolation</a></div>
<script>
const entries=__DATA__;const player=document.getElementById('player');let selected=0;
function choose(index){selected=index;const e=entries[index];player.pause();document.getElementById('clock').textContent='0.00 / 15.00 s';player.src=e.url;player.poster=e.poster;player.load();document.getElementById('description').textContent=e.subtitle;for(const [id,key] of [['download','download'],['direction','direction'],['music','source']])document.getElementById(id).href=e[key];document.querySelectorAll('.choice').forEach((x,i)=>{x.classList.toggle('active',i===index);x.setAttribute('aria-pressed',String(i===index))});const cuts=document.getElementById('cuts');cuts.replaceChildren();for(const [time,text] of e.cuts){const b=document.createElement('button');b.textContent=text;b.setAttribute('aria-label','Cue '+text);b.onclick=()=>{player.pause();player.currentTime=time};cuts.appendChild(b)}}
entries.forEach((e,i)=>{const b=document.createElement('button');b.className='choice';b.setAttribute('aria-label','Select '+e.title);b.innerHTML='<img src="'+e.poster+'" alt=""><span><span class="num">'+e.number+' / 15 SEC</span><b>'+e.title+'</b><small>'+e.track+' · '+e.artist+'</small></span>';b.onclick=()=>choose(i);document.getElementById('list').appendChild(b)});
document.getElementById('play').onclick=()=>{player.muted=false;player.volume=1;player.play()};document.getElementById('pause').onclick=()=>player.pause();document.getElementById('restart').onclick=()=>{player.currentTime=0;player.muted=false;player.volume=1;player.play()};player.addEventListener('timeupdate',()=>document.getElementById('clock').textContent=player.currentTime.toFixed(2)+' / '+(Number.isFinite(player.duration)?player.duration:15).toFixed(2)+' s');choose(0);
</script></body></html>'''
page=page.replace('__DATA__',json.dumps(entries,ensure_ascii=False).replace('</','<\\/'))
out=ROOT/'shorts/review/batch01';out.mkdir(exist_ok=True);(out/'index.html').write_text(page)
(ROOT/'shorts/review/index.html').write_text(page)
(out/'catalog.json').write_text(json.dumps(entries,ensure_ascii=False,indent=2))
print(out/'index.html')
